  'guide.room.chat.assistant.ask': "อยากให้ผมช่วยไกด์หน้าผู้ช่วยไหมครับ? ผมพาลองคุยกับเอเจนต์ เลือกทีม และส่งงานจริงให้ดูทีละขั้นได้ครับ",
