  'guide.room.chat.coding.use': "ระบบแผนที่โค้ดช่วยให้เอเจนต์เห็นไฟล์ สัญลักษณ์ และความเชื่อมโยงสำคัญของโปรเจกต์ผ่านเครื่องมือเพียงไม่กี่ call แทนการไล่อ่านไฟล์ครึ่งโปรเจกต์ก่อนเริ่มงานครับ",
  'guide.room.chat.coding.ask': "อยากให้ผมช่วยไกด์หน้าโค้ดไหมครับ? ผมพาดูเทอร์มินัล ไฟล์ Git ไทม์ไลน์ Pull requests และแผนที่โค้ดทีละจุดได้ครับ",
