  'guide.room.lines.what': "ห้องทำงานและการสื่อสารของทีม",
  'guide.page.chat.use': "ปกติคนจะเริ่มจากพิมพ์งานหรือคำถาม แล้วค่อยแนบไฟล์ เลือกโมเดล หรือให้ผู้ช่วยลงมือทำต่อครับ",
  'guide.page.chat.ask': "วันนี้อยากให้ Aetox ตอบคำถาม ช่วยแก้โค้ด หรือรับงานไปทำให้ครับ?",
  'guide.page.office.use': "ปกติใช้ดูโต๊ะทำงาน สร้างทีม และมอบงานที่ต้องให้เอเจนต์หลายตัวช่วยกันครับ",
