  'guide.account.guide.what': "เปิดไกด์ — ตัวที่เดินพาไปถึงปุ่มจริงแล้วบอกว่ามันคืออะไร ถามได้ว่าอะไรอยู่ไหน หรือคลิกอะไรก็ได้บนจอแล้วให้มันอธิบาย กด F1 ก็เปิดได้",
  'guide.account.guide.why': "ไกด์อยู่ข้างทัวร์เพราะทำคนละอย่าง: ทัวร์เล่าเรื่องครั้งเดียว ไกด์ตอบสิ่งที่ยังไม่เข้าใจได้ทุกวัน และตอบได้แม้ยังไม่ต่อสมอง",
