  'guide.settings.about.guide_btn.why': "ทุกที่ที่เปิดทัวร์ซ้ำได้ ต้องเปิดไกด์ได้ด้วย — คนที่กลับมาหาทัวร์คือคนที่กำลังหาคำตอบ",
  'guide.sidebar.projects.name': "โปรเจกต์",
  'guide.sidebar.projects.what': "แชททุกอันเกาะอยู่กับโฟลเดอร์งาน ไม่ได้เรียงตามวันอย่างเดียว เปิดโปรเจกต์แล้วแชทเก่าของงานนั้นอยู่ตรงนี้ทั้งหมด",
  'guide.sidebar.projects.why': "โปรเจกต์คือโฟลเดอร์ของบทสนทนา ไม่ใช่รั้ว — โฟลเดอร์จริงบนดิสก์คือหลักฐานเดียวว่าโปรเจกต์มีอยู่ ไม่มีตารางในฐานข้อมูล สร้างใน Explorer ก็นับเป็นโปรเจกต์",
  'guide.sidebar.open_folder.name': "เปิดโฟลเดอร์",
