  'guide.sidebar.create_project.what': "สร้างโฟลเดอร์งานใหม่พร้อมเริ่มแชทแรกของโปรเจกต์ทันที",
  'guide.sidebar.create_project.why': "โฟลเดอร์คือตัวโปรเจกต์เอง — สร้างที่นี่หรือสร้างใน Explorer ก็เป็นโปรเจกต์เท่ากัน ย้าย เปลี่ยนชื่อ ลบ ได้จากข้างนอกโดยไม่ต้องบอกแอป",
  'guide.sidebar.create_project_name.name': "ชื่อโปรเจกต์",
  'guide.sidebar.create_project_name.what': "กำหนดชื่อโฟลเดอร์งานใหม่",
  'guide.sidebar.create_project_move.name': "เปลี่ยนที่เก็บ",
  'guide.sidebar.create_project_move.what': "เลือกไดเรกทอรีปลายทางสำหรับวางโฟลเดอร์โปรเจกต์",
