  'guide.account.companion.name': "ตัวช่วยบนจอ",
  'guide.account.companion.what': "สลับเปิดหรือปิดตัวละครมาสคอตที่ลอยอยู่บนหน้าต่าง",
  'guide.account.tour.name': "รู้จักกับ Aetox",
  'guide.account.tour.what': "เปิดภาพรวม 4 ฉากของตัวแอป ผู้ช่วย ข้อมูล และการใช้ทรัพยากรเทียบกับ harness อื่น",
  'guide.account.tour.why': "ทัวร์อยู่หลังเลือกภาษาและก่อนต่อสมอง เพราะขั้นต่อสมองถามสิ่งที่คนใหม่ยังตอบไม่ได้ — และเปิดซ้ำได้จากสามที่ ไม่ใช่ดูได้แค่ครั้งแรก",
  'guide.account.update_check.name': "ตรวจสอบอัปเดต",
  'guide.account.update_check.what': "ตรวจเช็คเวอร์ชันใหม่ของ Aetox จากเซิร์ฟเวอร์",
  'guide.account.update_check.why': "อัปเดตที่ไม่มีใครบอกคืออัปเดตที่ไม่มีใครได้ — แอปดาวน์โหลด ตรวจลายเซ็น แล้วรีสตาร์ทเข้าตัวใหม่ได้เองมาตั้งแต่ 0.9.4 แต่ไม่เคยมีอะไรบอก ตอนนี้เช็กเองเงียบ ๆ และปุ่มนี้คือ \"อยากรู้เดี๋ยวนี้\"",
  'guide.account.settings.name': "ตั้งค่าระบบ",
  'guide.account.settings.what': "เปิดหน้าต่างการตั้งค่าหลักของ Aetox",
  'guide.topbar.door.name': "สลับระหว่างผู้ช่วยกับโค้ด",
  'guide.topbar.door.what': "เลือกพื้นที่ทำงานให้ตรงกับงาน: ผู้ช่วยสำหรับงานบนคอมพิวเตอร์ทั่วไป หรือโค้ดสำหรับโปรเจกต์ซอฟต์แวร์ที่ซับซ้อน",
  'guide.topbar.door.why': "ผู้ช่วยกับโค้ดแยกกันเพราะขอบเขต เครื่องมือ พื้นที่ทำงาน และบริบทไม่เหมือนกัน จึงโฟกัสงานและควบคุมความปลอดภัยได้ชัดเจนกว่า",
  'guide.topbar.door.common': "เลือกผู้ช่วยเมื่อจะจัดการไฟล์ ใช้เบราว์เซอร์ หาข้อมูล หรือทำเอกสาร เลือกโค้ดเมื่อจะสำรวจรีโป สร้างระบบ แก้บั๊ก รันเทสต์ หรือทำงานกับ Git ครับ",
  'guide.topbar.door.recommend': "ถ้างานไม่ผูกกับรีโปให้เริ่มที่ผู้ช่วย ถ้างานต้องเข้าใจและแก้หลายไฟล์ในโปรเจกต์ให้เลือกโค้ด การสลับประตูไม่เปิดแอปใหม่และไม่ทำให้งานอีกฝั่งหายครับ",
  'guide.topbar.door.assistant.name': "ไปที่ผู้ช่วย",
  'guide.topbar.door.assistant.what': "เปิดพื้นที่ผู้ช่วยสำหรับจัดการไฟล์ ควบคุมเบราว์เซอร์ หาข้อมูล และแก้ปัญหาในคอมพิวเตอร์",
  'guide.topbar.door.assistant.why': "ฝั่งผู้ช่วยออกแบบให้ใช้โมเดลบนเครื่องได้ ข้อมูลจึงอยู่ในเครื่องเมื่อคุณเลือกใช้แบบโลคอล",
  'guide.topbar.door.coding.name': "ไปที่โค้ด",
  'guide.topbar.door.coding.what': "เปิดพื้นที่สำหรับสร้างระบบและจัดการโปรเจกต์โค้ดที่มีไฟล์ซับซ้อน",
  'guide.topbar.door.coding.why': "ฝั่งโค้ดเตรียมขอบเขตไฟล์และการขออนุญาตไว้สำหรับโมเดลภายนอกที่ต้องใช้ความแม่นยำสูง",
