  'guide.settings.brain.hero.common': "ปกติผู้ใช้จะเริ่มจากเชื่อมบัญชี ChatGPT ผ่าน Codex เพราะใช้งานโมเดลโค้ดได้ด้วยแผนที่มีอยู่โดยไม่ต้องจัดการ API key เพิ่ม ถ้าทำงานโค้ดเบสใหญ่หรืองานที่ต้องการความแม่นยำสูง มักเพิ่ม API ภายนอกไว้เลือกโมเดลให้เหมาะกับงาน ส่วน Ollama หรือ LM Studio เหมาะเมื่อข้อมูลต้องอยู่ในเครื่องทั้งหมดครับ\n\nอยากให้ผมแนะนำผู้ให้บริการตามงาน งบ และสเปกเครื่องไหมครับ?",
