  'guide.capability.rail.mcp_library.what': "จุดเริ่มต้นสำหรับเพิ่ม MCP เลือกเซิร์ฟเวอร์สำเร็จรูปที่ผ่านการจัดหมวดและมีรายละเอียดการเชื่อมต่อให้ดูก่อน",
  'guide.capability.rail.mcp_library.common': "ปกติผู้ใช้จะค้นหาบริการที่ต้องการในห้องสมุดก่อน เพราะเพิ่มได้ง่ายกว่าและเห็นเรื่องการเข้าสู่ระบบ จำนวนเครื่องมือ และต้นทุนโทเคนครับ",
  'guide.capability.rail.mcp_library.recommend': "เริ่มจากห้องสมุดเสมอ ถ้าไม่มีเซิร์ฟเวอร์ที่ต้องการจริง ๆ ค่อยใช้ “เพิ่มด้วยที่อยู่” ด้านล่างเพื่อกรอก HTTP หรือ stdio เองครับ",
  'guide.capability.rail.skills.name': "สกิลของคุณ",
  'guide.capability.rail.skills.what': "หน้าจัดการชุดทักษะคำสั่ง (Skills) บนเครื่อง",
  'guide.capability.rail.skills.why': "สกิลย้ายออกจากตั้งค่ามาที่นี่ทั้งก้อน — เพราะมันเปลี่ยนว่าผู้ช่วยทำอะไรได้ และของแบบนั้นอยู่ห้องเดียว",
  'guide.capability.rail.builtins.name': "เครื่องมือในตัว",
  'guide.capability.rail.builtins.what': "รายชื่อเครื่องมือมาตรฐานที่มาพร้อมกับโปรแกรม",
  'guide.capability.rail.builtins.why': "เครื่องมือในตัวก็เป็น \"สิ่งที่ผู้ช่วยทำได้\" — เลยอยู่ห้องเดียวกับ MCP และสกิล ไม่ใช่ในตั้งค่า",
  'guide.capability.rail.builtins.common': "ปกติใช้ตรวจว่าเอเจนทำอะไรได้จากแกนของ Aetox เช่น ไฟล์ เชลล์ เอกสาร OCR เสียง หรือโค้ด ความสามารถเหล่านี้มาจากระบบ ไม่ได้ขึ้นกับขนาดโมเดลอย่างเดียวครับ",
  'guide.capability.rail.builtins.recommend': "เริ่มดูตามหมวดงานที่ต้องใช้ก่อน เครื่องมือในตัวถูกเตรียมและควบคุมโดย Aetox จึงเหมาะเป็นฐานหลักก่อนเพิ่มความสามารถภายนอกครับ",
  'guide.capability.rail.computer.name': "การใช้คอมพิวเตอร์",
  'guide.capability.rail.computer.what': "จัดการสิทธิ์การสั่งงานโปรแกรมอื่นบนหน้าจอ",
  'guide.capability.rail.computer.why': "การใช้คอมพิวเตอร์เป็นความสามารถที่ปิดเป็นค่าเริ่มต้น และปิดแล้วเครื่องมือหายไปจากโมเดลเลย ไม่ใช่แค่ปฏิเสธ — เพราะเครื่องมือที่ลงทะเบียนแล้วปฏิเสธทำให้โมเดลวางแผนบนสิ่งที่ไม่จริง",
  'guide.capability.rail.computer.common': "ชั้นควบคุมเบราว์เซอร์ของ Aetox ชี้ตำแหน่งและป้ายชื่อองค์ประกอบให้โมเดลเป็นข้อความ ทำให้โมเดลเล็กหรือโมเดลที่ไม่มี vision คลิกได้โดยไม่ต้องเดาพิกัดจากภาพครับ",
  'guide.capability.rail.computer.recommend': "ความสามารถควบคุมคอมพิวเตอร์ปิดไว้เป็นค่าเริ่มต้น เปิดเฉพาะเมื่อจำเป็นและเลือกเฉพาะโปรแกรมที่ยอมให้แตะ เพื่อให้ขอบเขตยังตรวจสอบได้ครับ",
  'guide.capability.rail.connections.name': "การเชื่อมต่อ",
