  'guide.capability.rail.connections.why': "การเชื่อมต่อไปข้างนอกก็เปลี่ยนว่าผู้ช่วยทำอะไรได้ — จึงอยู่ห้องนี้ทั้งหัวข้อ",
  'guide.capability.rail.connections.common': "ปกติใช้เชื่อมบริการที่งานต้องอาศัย เช่น บัญชีออนไลน์หรือเซิร์ฟเวอร์เครื่องมือ เพื่อให้เอเจนทำงานข้ามระบบได้จากที่เดียวครับ",
  'guide.capability.rail.connections.recommend': "เพิ่มเฉพาะบริการที่ต้องใช้กับงานจริง และตรวจสิทธิ์ก่อนเชื่อม เพราะการเชื่อมต่อภายนอกทำให้ขอบเขตข้อมูลกว้างขึ้นครับ",
  'guide.capability.rail.prompts.name': "ชุดคำสั่งสำเร็จรูป",
  'guide.capability.rail.prompts.what': "เก็บพรอมต์ยาวที่ให้ผลลัพธ์ดีไว้เป็นคำสั่งลัด เรียกใช้ซ้ำด้วย /ชื่อ และกลับมาแก้ไขได้",
  'guide.capability.rail.prompts.common': "ปกติใช้เก็บรูปแบบคำสั่งที่ต้องใช้ซ้ำ แต่เคยกระจัดกระจายตามแชทหรือคัดลอกมาจากหลายที่จนหาไม่เจอครับ",
