  'guide.capability.mcp.header.common': "ปกติใช้ตรวจว่าเซิร์ฟเวอร์ตัวไหนพร้อมใช้งาน ทดสอบการเชื่อมต่อ หรือเพิ่ม MCP ที่งานต้องใช้ครับ",
