  'guide.team.lead_select.what': "เลือกเอเจนที่มีอยู่แล้วให้เข้าร่วมทีมนี้ โดยเลือกได้เฉพาะคนที่อยู่ฝั่งเดียวกัน",
  'guide.team.lead_select.why': "ทีมหนึ่งผูกกับโต๊ะเดียว เพื่อให้เพดานเครื่องมือและขอบเขตงานของผู้ช่วยกับโค้ดไม่ปะปนกัน",
  'guide.team.lead_select.common': "ปกติเลือกสมาชิกที่มีหน้าที่ต่างกันแต่ส่งต่องานกันได้ เช่น คนค้นข้อมูล คนสรุป และคนสร้างผลงานครับ",
  'guide.team.lead_select.recommend': "เริ่มจากสมาชิก 2–3 คนก่อน แต่ละคนควรมีหน้าที่ชัดและไม่ซ้ำกันมากเกินไปครับ",
  'guide.team.add_member_btn.name': "สร้างพนักงานเพิ่ม",
