  'guide.team.add_member_btn.why': "การสร้างพนักงานกับการเลือกสมาชิกเป็นคนละขั้น ปุ่มนี้จึงใช้เฉพาะเมื่อยังไม่มีเอเจนที่เหมาะ ไม่ใช่ปุ่มบันทึกทีม",
