  'guide.background.panel.why': "งานที่มอบให้คนอื่นไม่จบเมื่อประโยคจบ — ถาดนี้มีค่าเพราะงานข้างในยังวิ่งอยู่ขณะบทสนทนาเดินต่อ ถาดเหนืองานที่ตายพร้อมคำตอบคือกล่องเปล่า",
