  // Guide System Concepts
  'guide.concept.stance.name': "แนวคิด: ระดับการลงมือ (Stance)",
  'guide.concept.stance.what': "ระดับความอิสระของเอเจนในการทำงาน ตั้งแต่ถามก่อนทุกคำสั่ง จนถึงการลงมือทำงานทันที",
  'guide.concept.stance.why': "สิ่งที่อยู่บนโต๊ะกับวิธีที่เทิร์นวิ่งเป็นคนละแกน — ระดับการลงมือคือแกนหลัง เปลี่ยนได้โดยไม่เปลี่ยนโต๊ะ (§106)",
  'guide.concept.desk_separation.name': "แนวคิด: การแยกโต๊ะทำงาน (Desk Separation)",
  'guide.concept.desk_separation.what': "ผู้ช่วยถูกจูนสำหรับงานบนเครื่องและการทำงาน local-first ส่วนโค้ดถูกจูนสำหรับโปรเจกต์ซับซ้อนและโมเดลความแม่นยำสูง โดยมีรั้วโปรเจกต์กับด่านอนุญาตคุมการเข้าถึง",
  'guide.concept.desk_separation.why': "บริษัทเดียว สองประตู — แอปและข้อมูลชุดเดียวกัน แต่ระบบเตรียมเครื่องมือ ขอบเขต และบริบทต่างกันให้ตรงกับงาน (§86)",
  'guide.concept.memory_system.name': "แนวคิด: ระบบความจำ (Memory System)",
  'guide.concept.memory_system.what': "ระบบที่เอเจนเสนอข้อมูลสำคัญเพื่อขออนุมัติให้จำลงเครื่อง โดยผู้ใช้เป็นเจ้าของและควบคุมได้ 100%",
  'guide.concept.memory_system.why': "ความจำต้องผ่านการอนุมัติของผู้ใช้เสมอ ไม่แอบจำ และบันทึกเป็นไฟล์ในเครื่อง (§279)",
  'guide.concept.brain_providers.name': "แนวคิด: การเชื่อมต่อสมอง (Brain Providers)",
  'guide.concept.brain_providers.what': "การเชื่อมโยงกับโมเดลภายนอก (OpenAI, Claude, Gemini) หรือรันในเครื่องผ่าน Ollama",
  'guide.concept.brain_providers.why': "รองรับโมเดลหลากหลายทั้งแบบคลาวด์และแบบโลคอลเพื่อความเป็นส่วนตัวและควบคุมค่าใช้จ่าย (§279)",
  'guide.concept.capability_room.name': "แนวคิด: ห้องความสามารถ (Capability Room)",
  'guide.concept.capability_room.what': "ศูนย์รวมการจัดการทักษะภายนอก ทั้ง MCP Server, Custom Skills, และ Builtin Tools",
  'guide.concept.capability_room.why': "ทุกอย่างที่เปลี่ยนความสามารถของเอเจนรวมอยู่ในห้องเดียว ไม่กระจัดกระจาย (§265)",
  'guide.concept.guide_system.name': "แนวคิด: ระบบไกด์ (Guide System)",
  'guide.concept.guide_system.what': "แกนแผนที่ตายตัวเป็นคนพาไปทีละปุ่ม ส่วนโมเดลมีหน้าที่เลือกเส้นทางและตอบคำถามเฉพาะหน้าที่กำลังยืนอยู่",
  'guide.concept.guide_system.why': "หัวใจไม่ใช่ความสามารถของโมเดล แต่คือสถาปัตยกรรมที่ควบคุมวิธีคิด — โมเดลตัดสินใจบนทางที่ระบบตรวจไว้แล้ว จึงไม่ต้องแบกการนำทางทั้งแอป (§293)",
  'guide.concept.office_multiagent.name': "แนวคิด: ระบบหลายเอเจน (Multi-Agent Office)",
  'guide.concept.office_multiagent.what': "ฐานการทำงานร่วมกันของหัวหน้าทีมและเอเจนเฉพาะทาง แต่ละคนมีโมเดล ความจำ เครื่องมือ และหน้าที่ของตัวเอง",
  'guide.concept.office_multiagent.why': "สิ่งที่เห็นวันนี้เป็นโครงฐานของเป้าหมายระยะยาว: ทีมเอเจนต์ที่แบ่งบทบาทและประสานงานกันได้ใกล้เคียงบริษัทหนึ่ง (§85)",
  'guide.concept.voice_interaction.name': "แนวคิด: การสั่งงานด้วยเสียง (Voice Interaction)",
  'guide.concept.voice_interaction.what': "การพูดคุยและฟังเสียงตอบกลับของเอเจนผ่านระบบแปลงเสียงในเครื่องหรือคลาวด์",
  'guide.concept.voice_interaction.why': "เสียงเป็นช่องทางธรรมชาติในการสื่อสาร โดยเก็บการตั้งค่าและการแปลงเสียงเป็นข้อมูลระบบ (§215)",
  'guide.concept.user_profile.name': "แนวคิด: ข้อมูลเกี่ยวกับคุณ (User Profile)",
  'guide.concept.user_profile.what': "ข้อมูลบริบทของผู้ใช้ เพื่อให้เอเจนเข้าใจเป้าหมายและสไตล์การทำงานข้ามทุกห้อง",
  'guide.concept.user_profile.why': "ข้อมูลว่าผู้ใช้คือใครไม่ใช่แค่การตั้งค่าเครื่อง แต่ถูกส่งไปยังทุกการสนทนาอย่างโปร่งใส (§229)",

